import { Exclude, Expose, Transform } from 'class-transformer';
import { Role } from '../../RBAC/role.enum';

export class UserEntity {

  // 👈 Handles both user_id (users) and organizer_id (organizers)
  @Expose()
  @Transform(({ obj }) => obj.user_id || obj.organizer_id)
  user_id!: string;

  // 👈 Handles both user_name (users) and organizer_name (organizers)
  @Expose()
  @Transform(({ obj }) => obj.user_name || obj.organizer_name)
  user_name!: string;

  // 👈 Handles both user_email (users) and organizer_email (organizers)
  @Expose()
  @Transform(({ obj }) => obj.user_email || obj.organizer_email)
  user_email!: string;

  // 👈 Excludes both password field variants
  @Exclude()
  user_password!: string;

  @Exclude()
  organizer_password!: string;

  @Expose()
  role!: Role;

  @Expose()
  date_created!: string;

  constructor(partial: Partial<UserEntity>) {
    Object.assign(this, partial);
  }
}

